import Ajax from 'core/ajax';

/**
 * Delete given job.
 *
 * @param {Number} id
 * @return {Promise}
 */
export const deleteJob = id => {
    const request = {
        methodname: 'tool_organisation_job_delete',
        args: {id}
    };

    return Ajax.call([request])[0];
};

/**
 * Delete manually assigned manager.
 *
 * @param {Number} userid
 * @param {Number} managerid
 * @return {Promise}
 */
export const deleteManuallyAssignedManager = (userid, managerid) => {
    return deleteManuallyAssignedManagers([userid], [managerid]);
};


/**
 * Delete manually assigned managers.
 *
 * @param {Number[]} userids
 * @param {Number[]} managerids
 * @param {boolean} unassignall
 * @return {Promise}
 */
export const deleteManuallyAssignedManagers = (userids, managerids, unassignall = false) => {
    const request = {
        methodname: 'tool_organisation_unassign_managers',
        args: {
            users: userids.map(userid => ({id: userid})),
            managers: managerids.map(managerid => ({id: managerid})),
            unassignall: unassignall,
        }
    };

    return Ajax.call([request])[0];
};